import _fs from 'node:fs';
import _path from 'node:path';
import { genericStateObjects, type ObjectDefinitionTree } from '../const/definition';
import type { PublicTransport } from '../types/Adapter';
// only change this for other adapters
export type AdapterClassDefinition = PublicTransport;

export type LibraryStateVal = LibraryStateValJson;
type LibraryStateValJson = {
    type: ioBroker.ObjectType;
    stateTyp: string | undefined;
    val: ioBroker.StateValue | undefined;
    ts: number;
    ack: boolean;
    obj: ioBroker.Object | undefined;
    init: boolean;
};

// Generic library module and base classes, do not insert specific adapter code here.

/**
 * Base class with this.log function.
 */
export class BaseClass {
    unload: boolean = false;
    log: CustomLog;
    adapter: AdapterClassDefinition;
    library: Library;
    name: string = ``;
    friendlyName: string = ``;

    constructor(adapter: AdapterClassDefinition, name: string = '', logName: string = '') {
        this.name = name;
        this.friendlyName = logName ? logName : this.name;
        this.log = new CustomLog(adapter, this.friendlyName);
        this.adapter = adapter;
        this.library = adapter.library;
    }
    async delete(): Promise<void> {
        this.unload = true;
    }
}

class CustomLog {
    #adapter: AdapterClassDefinition;
    #prefix: string;
    constructor(adapter: AdapterClassDefinition, text: string = '') {
        this.#adapter = adapter;
        this.#prefix = text;
    }
    getName(): string {
        return this.#prefix;
    }
    debug(log: string, log2: string = ''): void {
        this.#adapter.log.debug(log2 ? `[${log}] ${log2}` : `[${this.#prefix}] ${log}`);
    }
    info(log: string, log2: string = ''): void {
        this.#adapter.log.info(log2 ? `[${log}] ${log2}` : `[${this.#prefix}] ${log}`);
    }
    info2(log: string, log2: string = ''): void {
        if (!this.#adapter.config.suppressInfoLogs) {
            this.#adapter.log.info(log2 ? `[${log}] ${log2}` : `[${this.#prefix}] ${log}`);
        }
    }
    warn(log: string, log2: string = ''): void {
        this.#adapter.log.warn(log2 ? `[${log}] ${log2}` : `[${this.#prefix}] ${log}`);
    }
    error(log: string, log2: string = ''): void {
        this.#adapter.log.error(log2 ? `[${log}] ${log2}` : `[${this.#prefix}] ${log}`);
    }
    setLogPrefix(text: string): void {
        this.#prefix = text;
    }
}

export class Library extends BaseClass {
    private stateDataBase: { [key: string]: LibraryStateVal } = {};
    private forbiddenDirs: string[] = [];
    private translation: Record<'custom' | 'standard', { [key: string]: string }> = { custom: {}, standard: {} };
    private unknownTokens: Record<string, string> = {};
    private unknownTokensInterval: ioBroker.Interval | undefined;
    // Cache aller Sprach-Übersetzungen für getTranslationObj(): einmal laden,
    // dann synchron nachschlagen statt pro Key 11x zu importieren. undefined = noch nicht geladen.
    private allTranslations: Partial<Record<ioBroker.Languages, Record<string, string>>> | undefined;
    defaults = {
        updateStateOnChangeOnly: true,
    };

    constructor(adapter: AdapterClassDefinition, _options: unknown = null) {
        super(adapter, 'library');
        this.stateDataBase = {};
    }

    async init(): Promise<void> {
        await this.checkLanguage();
        if (this.adapter.config.logUnknownTokens) {
            this.unknownTokensInterval = this.adapter.setInterval(() => {
                this.log.info(`Unknown tokens: ${JSON.stringify(this.unknownTokens)}`);
            }, 60_000);
        }
    }

    /**
     * Stoppt laufende Timer/Intervalle der Library. Muss in onUnload() aufgerufen werden.
     */
    destroy(): void {
        if (this.unknownTokensInterval) {
            this.adapter.clearInterval(this.unknownTokensInterval);
            this.unknownTokensInterval = undefined;
        }
    }

    /**
    /**
     * Write/create states and channels from a JSON subtree using a definition.
     *
     * Parallelization:
     * - Parent channel is created first (sequential).
     * - Children (array items or object keys) are processed in parallel with a concurrency limit.
     *
     * @param prefix       ioBroker datapoint prefix to write into (e.g., "adapter.0.foo")
     * @param objNode      JSON-path into the definition (used by getObjectDefFromJson)
     * @param def          Definition JSON (mapping of nodes to Channel/State object definitions)
     * @param data         Source JSON subtree to materialize under `prefix`
     * @param expandTree   If true, arrays below a state are expanded into channels instead of being stringified
     * @param concurrency  Max number of parallel child writes (default: 8)
     * @returns Promise<void>
     */
    async writeFromJson(
        prefix: string,
        objNode: string,
        def: ObjectDefinitionTree,
        data: unknown,
        expandTree: boolean = false,
        concurrency: number = 8,
    ): Promise<void> {
        // Type guards
        if (!def || typeof def !== 'object') {
            return;
        }
        const t = typeof data;
        if (data === undefined || (t !== 'string' && t !== 'number' && t !== 'boolean' && t !== 'object')) {
            return;
        }

        // Resolve object definition for the current node
        const objectDefinition = objNode ? await this.getObjectDefFromJson(`${objNode}`, def, data) : null;

        if (objectDefinition) {
            objectDefinition.native = {
                ...(objectDefinition.native || {}),
                objectDefinitionReference: objNode,
            };
        }

        // Simple concurrency limiter (no dependency)
        const queue: Array<() => Promise<void>> = [];
        let active = 0;
        const runLimited = async <T>(task: () => Promise<T>): Promise<T> => {
            if (active >= concurrency) {
                await new Promise<void>(resolve => queue.push(async () => resolve()));
            }
            active++;
            try {
                return await task();
            } finally {
                active--;
                const next = queue.shift();
                if (next) {
                    next().catch(() => void 0);
                }
            }
        };

        // Helper to process an array element (index -> channel + recurse)
        const processArrayItem = (idx: number, item: unknown): Promise<void> =>
            runLimited(async () => {
                if (!objectDefinition) {
                    return;
                }
                const defChannel = this.getChannelObject(objectDefinition);
                const dp = `${prefix}${`00${idx}`.slice(-2)}`; // e.g. foo.00, foo.01
                await this.writedp(dp, null, defChannel); // create folder
                await this.writeFromJson(dp, `${objNode}`, def, item, expandTree, concurrency);
            });

        // Helper to process an object key (key -> recurse)
        const processObjectKey = (key: string, value: unknown): Promise<void> =>
            runLimited(async () => {
                await this.writeFromJson(`${prefix}.${key}`, `${objNode}.${key}`, def, value, expandTree, concurrency);
            });

        // Branch: objects/arrays
        if (typeof data === 'object' && data !== null) {
            // Arrays
            if (Array.isArray(data)) {
                if (!objectDefinition) {
                    return;
                }

                // When definition says "state" and we don't expand: stringify once
                if (objectDefinition.type === 'state' && !expandTree) {
                    const serialized = JSON.stringify(data) || '[]';
                    await this.writeFromJson(prefix, objNode, def, serialized, expandTree, concurrency);
                    return;
                }

                // Else: expand array to child channels, process items in parallel (limited)
                const tasks = data.map((item, idx) => processArrayItem(idx, item));
                await Promise.all(tasks);
                return;
            }

            // Plain object
            // Ensure parent folder exists if we have a definition
            if (objectDefinition) {
                const defChannel = this.getChannelObject(objectDefinition);
                await this.writedp(prefix, null, defChannel);
            }

            // Null → nothing to do
            if (data === null) {
                return;
            }

            // Process keys in parallel (limited)
            const entries = Object.entries(data as Record<string, unknown>);
            const tasks = entries.map(([k, v]) => processObjectKey(k, v));
            await Promise.all(tasks);
            return;
        }

        // Primitives (string/number/boolean) — must be a state
        if (!objectDefinition) {
            return;
        }
        await this.writedp(prefix, data as ioBroker.StateValue, objectDefinition);
    }

    /**
     * Holt das ioBroker.Object aus der State-Definition.
     *
     * Ermittelt die Objektdefinition für einen State aus dem Definitions-JSON.
     * Falls keine Definition gefunden wird, wird basierend auf dem Datentyp eine Standard-Definition erstellt.
     * Spezialfall: Schlüssel die mit "_" beginnen erhalten eine customString-Definition.
     *
     * @param key Der Deep-Linking-Schlüssel zur Definition (Punkt-separierter Pfad)
     * @param def Das Definitionsobjekt
     * @param data Das Definitions-Dataset (wird zur Typ-Erkennung verwendet)
     * @returns ioBroker.ChannelObject | ioBroker.DeviceObject | ioBroker.StateObject | ioBroker.FolderObject | null
     */
    async getObjectDefFromJson(
        key: string,
        def: ObjectDefinitionTree,
        data: unknown,
    ): Promise<ioBroker.StateObject | ioBroker.ChannelObject | ioBroker.DeviceObject | ioBroker.FolderObject | null> {
        //let result = await jsonata(`${key}`).evaluate(data);
        // Ein gefundener Knoten wird als konkrete Objektdefinition interpretiert (so nutzt ihn
        // der restliche Code); deepJsonValue liefert generisch Baum-Knoten.
        let result = this.deepJsonValue(key, def) as
            | ioBroker.StateObject
            | ioBroker.ChannelObject
            | ioBroker.DeviceObject
            | ioBroker.FolderObject
            | null;
        if (result === null || result === undefined) {
            const k = key.split('.');
            if (k && k[k.length - 1].startsWith('_')) {
                result = genericStateObjects.customString;
                result = structuredClone(result);
            } else {
                this.log.debug(`No definition for ${key}!`);
                result = genericStateObjects.default;
                result = structuredClone(result);
                switch (typeof data) {
                    case 'number':
                    case 'bigint':
                        {
                            result.common.type = 'number';
                            result.common.role = 'value';
                        }
                        break;
                    case 'boolean':
                        {
                            result.common.type = 'boolean';
                            result.common.role = 'indicator';
                        }
                        break;
                    case 'string':
                        {
                            result.common.type = 'string';
                            result.common.role = 'text';
                        }
                        break;
                    case 'symbol':
                    case 'undefined':
                    case 'object':
                    case 'function':
                        {
                            result.common.type = 'string';
                            result.common.role = 'json';
                        }
                        break;
                }
            }
        } else {
            result = structuredClone(result);
        }
        return result;
    }

    /**
     * Extrahiert einen Wert aus einem verschachtelten JSON-Objekt anhand eines Punkt-separierten Pfades.
     *
     * Navigiert durch die Objektstruktur entlang des angegebenen Schlüsselpfads.
     * Gibt null zurück, wenn ein Zwischenwert undefined ist.
     *
     * @param key Punkt-separierter Pfad zum gewünschten Wert (z.B. "level1.level2.property")
     * @param data JSON-Objekt, aus dem der Wert extrahiert werden soll
     * @returns Der Wert am angegebenen Pfad oder null wenn nicht gefunden
     */
    deepJsonValue(key: string, data: ObjectDefinitionTree): ObjectDefinitionTree | ioBroker.Object | null {
        if (!key || !data || typeof data !== 'object' || typeof key !== 'string') {
            throw new Error(`Error(222) data or key are missing/wrong type!`);
        }
        const k = key.split(`.`);
        let c = 0;
        // Navigation durch beliebig tiefe Knoten: jeder Zwischenschritt ist wieder ein
        // ObjectDefinitionTree (Blätter sind ioBroker.Object). Cast nötig, da ioBroker.Object
        // selbst keine Index-Signatur hat.
        let s: ObjectDefinitionTree | ioBroker.Object | undefined = data;
        while (c < k.length) {
            s = (s as ObjectDefinitionTree)[k[c++]];
            if (s === undefined) {
                return null;
            }
        }
        return s ?? null;
    }

    /**
     * Gibt eine Channel/Device-Definition aus der _channel-Eigenschaft eines getObjectDefFromJson()-Ergebnisses
     * oder eine Standard-Definition zurück.
     *
     * @param definition Das Definitionsobjekt
     * @returns ioBroker.ChannelObject | ioBroker.DeviceObject oder ein Standard-Channel-Objekt
     */
    getChannelObject(
        definition: (ioBroker.Object & { _channel?: ioBroker.Object }) | null = null,
    ): ioBroker.ChannelObject | ioBroker.DeviceObject | ioBroker.FolderObject {
        const def = (definition && definition._channel) || null;
        const result: ioBroker.ChannelObject | ioBroker.DeviceObject | ioBroker.FolderObject = {
            _id: def ? def._id : '',
            type: def ? (def.type == 'channel' ? 'channel' : def.type === 'device' ? 'device' : 'folder') : 'folder',
            common: {
                name: (def && def.common && def.common.name) || 'no definition',
            },
            native: (def && def.native) || {},
        };
        return result;
    }

    /**
     * Schreibt/erstellt den angegebenen Datenpunkt mit einem Wert.
     *
     * Verhalten:
     * - Erstellt/erweitert das ioBroker-Objekt, wenn es nicht in der In-Memory-DB existiert.
     * - Channels/Devices werden erstellt/aktualisiert, aber niemals als States geschrieben.
     * - Für States wird nur geschrieben wenn:
     *   - `val !== undefined` und
     *   - (`defaults.updateStateOnChangeOnly` ist true) ODER (alter Wert unterscheidet sich) ODER (`forceWrite` ist true) ODER (`!node.ack`)
     * - Werte werden in den Ziel-ioBroker common.type konvertiert (falls verfügbar).
     * - Überspringt Schreiboperationen für nicht erlaubte Verzeichnisse (gemäß `isDirAllowed`).
     *
     * @param dp         Datenpunkt-ID (wird über `cleandp` normalisiert).
     * @param val        Neuer Wert (Channels/Devices verwenden `undefined` und werden nicht geschrieben).
     * @param obj        Objektdefinition für Erstellung/Erweiterung (Channel/Device/State); erforderlich wenn der Knoten neu ist.
     * @param ack        Bestätigungs-Flag für State-Schreibvorgang.
     * @param forceWrite Erzwingt Schreibvorgang auch wenn `val` dem alten Wert entspricht.
     * @returns Promise<void>
     */
    async writedp(
        dp: string,
        val: ioBroker.StateValue | undefined,
        obj:
            | ioBroker.ChannelObject
            | ioBroker.DeviceObject
            | ioBroker.FolderObject
            | ioBroker.StateObject
            | null = null,
        ack: boolean = true,
        forceWrite: boolean = false,
    ): Promise<void> {
        // Normalize id and check DB
        dp = this.cleandp(dp);
        let node = this.readdb(dp);
        const disallowed = !this.isDirAllowed(dp);

        // Create/extend object if not known yet
        if (node === undefined) {
            if (!obj) {
                throw new Error('writedp: trying to create a state without object information.');
            }

            // Ensure full _id (adapter namespace)
            obj._id = `${this.adapter.name}.${this.adapter.instance}.${dp}`;

            // Translate name if string
            if (typeof obj.common.name === 'string') {
                obj.common.name = await this.getTranslationObj(obj.common.name);
            }

            // Persist object unless path is disallowed.
            // Hinweis: extendObject merged common (inkl. states) bereits; ein separates
            // Vorab-Schreiben von common.states ist daher nicht nötig.
            if (!disallowed) {
                await this.adapter.extendObject(dp, obj);
            }

            const stateType = obj.type !== 'state' ? undefined : obj?.common?.type;
            node = this.setdb(dp, obj.type, undefined, stateType, true, Date.now(), obj);
        } else if (node.init && obj) {
            // Object already known in DB but marked as init → extend/update once
            if (typeof obj.common.name === 'string') {
                obj.common.name = await this.getTranslationObj(obj.common.name);
            }

            if (!disallowed) {
                await this.adapter.extendObject(dp, obj);
                node.init = false;
            }
        } else if (obj && !node.init) {
            // Object already known and initialised. The two branches above write common.name/desc
            // only on first creation and on the first post-restart touch; afterwards the metadata
            // was never refreshed. Dynamic channel names (leg route "A → B", station name, line
            // name) therefore went stale when a re-written leg changed its content (same slot,
            // different train/line/station). Refresh name/desc here whenever they actually changed
            // so a surviving leg follows its new content. NOTE: this only covers channels that ARE
            // written in this poll; legs that vanished entirely (journey shrank) are not visited
            // here and are handled by garbageColleting. Guarded by a value comparison
            // (JSON.stringify handles both plain strings and translation objects with their
            // deterministic key order) so an unchanged/static channel triggers no extendObject on
            // every poll.
            if (typeof obj.common.name === 'string') {
                obj.common.name = await this.getTranslationObj(obj.common.name);
            }
            const oldCommon = node.obj?.common;
            const nameChanged =
                obj.common.name !== undefined && JSON.stringify(oldCommon?.name) !== JSON.stringify(obj.common.name);
            const descChanged =
                obj.common.desc !== undefined && JSON.stringify(oldCommon?.desc) !== JSON.stringify(obj.common.desc);
            if (!disallowed && (nameChanged || descChanged)) {
                await this.adapter.extendObject(dp, obj);
                // Keep the in-memory object in sync so the next poll compares against the new
                // value and does not re-extend unnecessarily.
                node.obj = obj;
            }
        }

        // Touch container timestamp on every write so garbageColleting can tell a container that is
        // still present in this poll from one that vanished (all its states/legs are gone). Without
        // this, channels keep their creation ts forever and stale-container detection could not work.
        if (node && obj && obj.type !== 'state') {
            node.ts = Date.now();
        }

        // If the object exists and is NOT a state → nothing to write
        if (obj && obj.type !== 'state') {
            return;
        }

        // Update in-memory DB value unless it is a state with undefined value
        if (node && !(node.type === 'state' && val === undefined)) {
            this.setdb(dp, node.type, val, node.stateTyp, false, undefined, undefined, node.init);
        }

        // Decide whether to write the state value
        if (
            node &&
            val !== undefined &&
            (!this.defaults.updateStateOnChangeOnly || node.val != val || forceWrite || !node.ack)
        ) {
            // Convert to target type if necessary
            const targetType = obj?.common?.type ?? node.stateTyp;
            if (targetType && typeof val !== targetType) {
                val = this.convertToType(val, targetType as 'string' | 'number' | 'boolean' | 'array' | 'json');
            }

            if (!disallowed) {
                await this.adapter.setState(dp, {
                    val: val,
                    ts: Date.now(),
                    ack,
                });
            }
        }
    }

    /**
     * Prüft, ob ein Datenpunkt-Pfad erlaubt ist oder in der Liste der verbotenen Verzeichnisse enthalten ist.
     *
     * Datenpunkte mit maximal 2 Pfadsegmenten sind immer erlaubt.
     * Alle anderen werden gegen die Liste der verbotenen Verzeichnisse geprüft.
     *
     * @param dp Datenpunkt-ID, die geprüft werden soll
     * @returns true wenn der Pfad erlaubt ist, false wenn er verboten ist
     */
    isDirAllowed(dp: string): boolean {
        if (dp && dp.split('.').length <= 2) {
            return true;
        }
        for (const a of this.forbiddenDirs) {
            if (dp.includes(a)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Bereinigt den Objektbaum durch Löschen von Datenpunkten, die nicht mehr benötigt werden.
     *
     * Diese Methode durchläuft die State-Datenbank und entfernt Datenpunkte basierend auf Filter- und Hold-Kriterien.
     * Datenpunkte, die den Filter nicht erfüllen oder in der Hold-Liste enthalten sind, werden beibehalten.
     * Alle anderen werden aus der Datenbank entfernt und rekursiv aus ioBroker gelöscht.
     *
     * @param hold Array von Datenpunkt-Präfixen, die beibehalten werden sollen (nicht gelöscht)
     * @param filter Array von Datenpunkt-Präfixen zum Filtern oder null für alle Datenpunkte
     * @param deep Anzahl der Pfadsegmente, die für das Löschen berücksichtigt werden sollen
     * @returns Promise<void>
     */
    async cleanUpTree(hold: string[], filter: string[] | null, deep: number): Promise<void> {
        let del = [];
        for (const dp in this.stateDataBase) {
            if (filter && filter.filter(a => dp.startsWith(a) || a.startsWith(dp)).length == 0) {
                continue;
            }
            if (hold.filter(a => dp.startsWith(a) || a.startsWith(dp)).length > 0) {
                continue;
            }
            delete this.stateDataBase[dp];
            del.push(dp.split('.').slice(0, deep).join('.'));
        }
        del = del.filter((item, pos, arr) => {
            return arr.indexOf(item) == pos;
        });
        for (const a of del) {
            await this.adapter.delObjectAsync(a, { recursive: true });
            this.log.debug(`Clean up tree delete: ${a}`);
        }
    }

    /**
     * Remove forbidden chars from datapoint string.
     *
     * @param string Datapoint string to clean
     * @param lowerCase lowerCase() first param.
     * @param removePoints remove . from dp
     * @returns void
     */
    cleandp(string: string, lowerCase: boolean = false, removePoints: boolean = false): string {
        // Guard gegen Nicht-String-Eingaben: .replace() existiert nur auf echten
        // Strings. Mit && griff der Guard nur bei falsy UND Nicht-String (null,
        // undefined, 0, false) – eine truthy Nicht-String (Zahl != 0, Objekt,
        // Array) rutschte durch und ließ .replace() mit TypeError crashen.
        // || fängt alles falsy ODER Nicht-String ab, sodass .replace() garantiert
        // nur auf echten Strings läuft.
        if (!string || typeof string != 'string') {
            return string;
        }

        string = string.replace(this.adapter.FORBIDDEN_CHARS, '_');
        // hardliner
        if (removePoints) {
            string = string.replace(/[^0-9A-Za-z_-]/gu, '_');
        } else {
            string = string.replace(/[^0-9A-Za-z._-]/gu, '_');
        }
        return lowerCase ? string.toLowerCase() : string;
    }

    /**
     * Konvertiert einen beliebigen Wert in den angeforderten Zieltyp und gibt ein ioBroker.StateValue zurück.
     *
     * Regeln:
     * - 'string': Primitive -> String(value); Arrays/Objekte -> JSON-String.
     * - 'number': Zahlen bleiben; Booleans -> 1/0; Strings werden mit Komma-Unterstützung geparst ("1,23" -> 1.23); NaN -> 0.
     * - 'boolean': Booleans bleiben; Zahlen -> value !== 0; Strings -> gängige Wahrheitswerte-Schlüsselwörter; sonst Boolean(value).
     * - 'array' | 'json': immer JSON-String der Eingabe.
     *
     * @param value Eingabewert zum Konvertieren (kann Primitive, Array oder Objekt sein)
     * @param type  Zieltyp: 'string' | 'number' | 'boolean' | 'array' | 'json'
     * @returns Konvertierter Wert als ioBroker.StateValue (string | number | boolean | null)
     */
    convertToType(
        value: ioBroker.StateValue | unknown[] | Record<string, unknown> | null,
        type: 'string' | 'number' | 'boolean' | 'array' | 'json' | 'undefined' | 'object' | 'mixed',
    ): ioBroker.StateValue {
        if (value === null) {
            return null;
        }
        if (type === 'undefined') {
            throw new Error('convertToType: type "undefined" not allowed');
        }
        if (value === undefined) {
            value = '';
        }
        if (type === 'mixed') {
            if (['string', 'number', 'boolean'].includes(typeof value)) {
                return value as ioBroker.StateValue;
            }
            type = Array.isArray(value) ? 'array' : 'json';
        }
        if (type === 'object') {
            type = 'json';
        }

        // Helper: stringify objects/arrays safely
        const toJsonString = (v: unknown): string => JSON.stringify(v);

        switch (type) {
            case 'string': {
                if (typeof value === 'string') {
                    return value;
                }
                if (typeof value === 'object') {
                    return toJsonString(value);
                }
                return String(value);
            }

            case 'number': {
                if (typeof value === 'number' && Number.isFinite(value)) {
                    return value;
                }
                if (typeof value === 'boolean') {
                    return value ? 1 : 0;
                }
                if (typeof value === 'string') {
                    const n = Number(value.trim().replace(',', '.'));
                    return Number.isFinite(n) ? n : 0;
                }
                // objects/arrays → cannot parse meaningfully → 0
                return 0;
            }

            case 'boolean': {
                if (typeof value === 'boolean') {
                    return value;
                }
                if (typeof value === 'number') {
                    return value !== 0;
                }
                if (typeof value === 'string') {
                    const s = value.trim().toLowerCase();
                    if (['true', '1', 'on', 'yes', 'y'].includes(s)) {
                        return true;
                    }
                    if (['false', '0', 'off', 'no', 'n', ''].includes(s)) {
                        return false;
                    }
                    return Boolean(s);
                }
                // objects/arrays → truthiness
                return Boolean(value);
            }
            case 'array':
            case 'json': {
                // Always return JSON string for array/json targets
                return toJsonString(value);
            }
        }
    }

    readdb(dp: string): LibraryStateVal {
        return this.stateDataBase[this.cleandp(dp)];
    }

    setdb(
        dp: string,
        type: ioBroker.ObjectType | LibraryStateVal,
        val: ioBroker.StateValue | undefined = undefined,
        stateType: string | undefined = undefined,
        ack: boolean = true,
        ts: number = Date.now(),
        obj: ioBroker.Object | undefined = undefined,
        init: boolean = false,
    ): LibraryStateVal {
        if (typeof type == 'object') {
            // type = type as LibraryStateVal;
            this.stateDataBase[dp] = type;
        } else {
            // type = type as ioBroker.ObjectType;
            this.stateDataBase[dp] = {
                type: type,
                stateTyp:
                    stateType !== undefined
                        ? stateType
                        : this.stateDataBase[dp] !== undefined && this.stateDataBase[dp].stateTyp !== undefined
                          ? this.stateDataBase[dp].stateTyp
                          : undefined,
                val: val,
                ack: ack,
                ts: ts ? ts : Date.now(),
                obj:
                    obj !== undefined
                        ? obj
                        : this.stateDataBase[dp] !== undefined && this.stateDataBase[dp].obj !== undefined
                          ? this.stateDataBase[dp].obj
                          : undefined,
                init: init,
            };
        }
        return this.stateDataBase[dp];
    }

    async memberDeleteAsync(data: { delete: () => Promise<void> }[]): Promise<void> {
        if (this.unknownTokensInterval) {
            this.adapter.clearInterval(this.unknownTokensInterval);
        }
        for (const d of data) {
            await d.delete();
        }
    }

    async fileExistAsync(file: string): Promise<boolean> {
        if (_fs.existsSync(`./admin/${file}`)) {
            return true;
        }
        return false;
    }

    /**
     * Initialise the database with the states to prevent unnecessary creation and writing.
     *
     * @param states States that are to be read into the database during initialisation.
     * @returns void
     */
    async initStates(states: { [key: string]: { val: ioBroker.StateValue; ts: number; ack: boolean } }): Promise<void> {
        if (!states) {
            return;
        }
        this.stateDataBase = {};
        const removedChannels: string[] = [];
        for (const state in states) {
            const dp = state.replace(`${this.adapter.name}.${this.adapter.instance}.`, '');
            const del = !this.isDirAllowed(dp);
            if (!del) {
                const obj = await this.adapter.getObjectAsync(dp);
                // Store with the full, namespaced id so the key matches what writedp/readdb and
                // garbageColleting use at runtime. Stripping the namespace here caused a key-format
                // mismatch after a restart: writedp could not find the existing entry, recreated it
                // as undefined, and stale values could neither be overwritten nor garbage-collected.
                this.setdb(
                    this.cleandp(state),
                    'state',
                    states[state] ? states[state].val : undefined,
                    obj && obj.common && obj.common.type ? obj.common.type : undefined,
                    states[state] && states[state].ack,
                    states[state] && states[state].ts ? states[state].ts : Date.now(),
                    obj == null ? undefined : obj,
                    true,
                );
            } else {
                if (!removedChannels.every(a => !dp.startsWith(a))) {
                    continue;
                }
                const channel = dp.split('.').slice(0, 4).join('.');
                removedChannels.push(channel);
                await this.adapter.delObjectAsync(channel, { recursive: true });
                this.log.debug(`Delete channel with dp:${channel}`);
            }
        }

        // Channel-Objekte (device/channel/folder) ebenfalls laden. `states` (aus getStates)
        // enthaelt nur State-Datenpunkte; ohne die Channels fehlen sie nach jedem Neustart in
        // stateDataBase. garbageColleting kann dann verschwundene Channels nicht erkennen und ihre
        // stale common.name/desc nicht neutralisieren (die Neutralisierung lief bis hier nur im
        // Unit-Test, wo ein Channel kuenstlich injiziert wird). Alter ts, damit ein Channel, den
        // der naechste Poll nicht mehr schreibt, als "verschwunden" gilt; noch vorhandene Channels
        // werden beim Schreiben via writedp wieder auf Date.now() getoucht.
        for (const type of ['device', 'channel', 'folder'] as const) {
            let objs: Record<string, ioBroker.Object> = {};
            try {
                objs = await this.adapter.getForeignObjectsAsync(
                    `${this.adapter.name}.${this.adapter.instance}.*`,
                    type,
                );
            } catch (err) {
                this.log.warn(`initStates: could not load ${type} objects: ${(err as Error).message}`);
                continue;
            }
            for (const id in objs) {
                const dp = id.replace(`${this.adapter.name}.${this.adapter.instance}.`, '');
                if (!this.isDirAllowed(dp)) {
                    continue;
                }
                const obj = objs[id];
                this.setdb(this.cleandp(id), type, undefined, undefined, true, obj?.ts ?? 0, obj, true);
            }
        }
    }

    /**
     * Resets states that have not been updated in the database in offset time. Container objects
     * (channel/folder/device) that were not rewritten in this poll additionally get their
     * common.name/desc reset to a neutral placeholder (the id's leaf segment), so a vanished
     * leg/station/line no longer shows its old dynamic label over emptied states.
     *
     * @param prefix String with which states begin that are reset.
     * @param offset Time in ms since last update. Ignored when `since` is given.
     * @param del Delete the state if it is not updated.
     * @param since Cut-off timestamp: states older than this are considered stale. Callers that
     * write a batch of states first should pass the timestamp taken *before* the batch, otherwise
     * a batch taking longer than `offset` collects its own freshly written states (#87).
     * @returns void
     */
    async garbageColleting(prefix: string, offset: number = 2000, del = false, since?: number): Promise<void> {
        if (!prefix) {
            return;
        }
        const cutoff = since ?? Date.now() - offset;
        // Normalize the prefix exactly like writedp normalizes state ids (cleandp). Otherwise a
        // station/journey id containing forbidden chars (e.g. ':' in "de-DELFI_de:12072:900245002")
        // yields a raw prefix that never startsWith the sanitized db keys ("..._12072_..."), so
        // garbage collection silently matches nothing and stale values are never cleared (#82).
        prefix = this.cleandp(prefix);
        // Diagnose-Zähler: wie viele DB-Einträge unter dem Prefix gematcht wurden, wie viele davon
        // Channels (channel/folder/device) sind und wie viele davon neutralisiert wurden.
        let gcMatched = 0;
        let gcChannels = 0;
        let gcNeutralized = 0;
        if (this.stateDataBase) {
            for (const id in this.stateDataBase) {
                if (id.startsWith(prefix)) {
                    const state = this.stateDataBase[id];
                    if (!state) {
                        continue;
                    }
                    gcMatched++;
                    // Container objects (channel/folder/device) carry no value. When a container
                    // was not (re)written in this poll — e.g. a leg that vanished because the journey
                    // shrank — resetting only its states leaves the stale dynamic name ("A → B",
                    // line/station name) sitting over emptied data. Reset the metadata to a neutral
                    // placeholder (the id's leaf segment). Guarded by a value comparison so an already
                    // neutral or fresh container triggers no extendObject. Skipped for del=true (the
                    // whole subtree is removed) and for value states (val==undefined && type 'state'),
                    // which keep the existing reset path below.
                    if (state.val == undefined) {
                        if (state.type !== 'state') {
                            gcChannels++;
                        }
                        if (!del && state.type !== 'state' && state.obj?.common && state.ts < cutoff) {
                            const leaf = id.split('.').pop() ?? '';
                            const common = state.obj.common;
                            if (JSON.stringify(common.name) !== JSON.stringify(leaf) || (common.desc ?? '') !== '') {
                                await this.adapter.extendObject(id, { common: { name: leaf, desc: '' } });
                                common.name = leaf;
                                common.desc = '';
                                state.ts = Date.now();
                                gcNeutralized++;
                            }
                        }
                        continue;
                    }
                    if (state.ts < cutoff) {
                        if (del) {
                            await this.cleanUpTree([], [id], -1);
                            continue;
                        }
                        let newVal: -1 | '' | '{}' | '[]' | false | null | undefined;
                        switch (state.stateTyp) {
                            case 'string':
                                if (typeof state.val == 'string') {
                                    if (state.val.startsWith('{') && state.val.endsWith('}')) {
                                        newVal = '{}';
                                    } else if (state.val.startsWith('[') && state.val.endsWith(']')) {
                                        newVal = '[]';
                                    } else {
                                        newVal = '';
                                    }
                                } else {
                                    newVal = '';
                                }
                                break;
                            case 'bigint':
                            case 'number':
                                newVal = -1;
                                break;

                            case 'boolean':
                                newVal = false;
                                break;
                            case 'symbol':
                            case 'object':
                            case 'function':
                                newVal = null;
                                break;
                            case 'undefined':
                                newVal = undefined;
                                break;
                        }
                        await this.writedp(id, newVal);
                    }
                }
            }
        }
        this.log.debug(
            `garbageColleting ${prefix}: matched=${gcMatched} channels=${gcChannels} neutralized=${gcNeutralized}`,
        );
    }

    getLocalLanguage(): ioBroker.Languages {
        if (this.adapter.language) {
            return this.adapter.language;
        }
        return 'en';
    }
    getTranslation(key: string | null | undefined): string {
        if (!key) {
            return '';
        }
        if (this.translation.standard[key] !== undefined) {
            return this.translation.standard[key];
        }
        if (this.translation.custom[key] !== undefined) {
            return this.translation.custom[key];
        }
        if (this.adapter.config.logUnknownTokens) {
            this.unknownTokens[key] = '';
        }
        return key;
    }
    existTranslation(key: string): boolean {
        if (this.translation.standard[key] !== undefined) {
            return true;
        }
        if (this.translation.custom[key] !== undefined) {
            return true;
        }
        return false;
    }

    // === i18n: einzige Quelle für unterstützte Sprachen & Dateipfade. ===
    // Ändern sich Verzeichnis oder Dateiname der Übersetzungen, NUR hier anpassen.
    private static readonly SUPPORTED_LANGUAGES: ioBroker.Languages[] = [
        'en',
        'de',
        'ru',
        'pt',
        'nl',
        'fr',
        'it',
        'es',
        'pl',
        'uk',
        'zh-cn',
    ];
    private standardTranslationPath(language: ioBroker.Languages | undefined): string {
        // Kurzform `<lang>.json`. Der frühere Pfad `<lang>/translations.json` zeigte seit dem
        // Umbau auf kurze Dateinamen ins Leere: Es fand sich KEINE Sprachdatei mehr, also warnte
        // der Adapter für alle 11 Sprachen und getTranslationObj() gab jeden Schlüssel roh zurück.
        return _path.join(__dirname, `../../../admin/i18n/${language}.json`);
    }
    private customTranslationPath(language: ioBroker.Languages | undefined): string {
        return _path.join(__dirname, `../../../admin/custom/i18n/${language}.json`);
    }

    /**
     * Liest eine Sprachdatei von der Platte.
     *
     * Bewusst `readFileSync` statt `await import()`: Ein dynamischer JSON-Import verhält sich je
     * nach Modulsystem verschieden – im gebauten CommonJS wird er zu `require` (funktioniert),
     * unter ts-node/ESM verlangt er dagegen ein `with { type: 'json' }` und wirft sonst. Der
     * Dateizugriff ist in beiden Welten identisch und damit auch im Test prüfbar.
     *
     * @param path Absoluter Pfad der Sprachdatei
     */
    private loadTranslationFile(path: string): Record<string, string> {
        return JSON.parse(_fs.readFileSync(path, 'utf8')) as Record<string, string>;
    }

    /**
     * Lädt die Übersetzungen aller unterstützten Sprachen einmalig in den Cache.
     * Folgeaufrufe sind No-Ops. try/catch pro Datei: eine fehlende Sprachdatei lässt
     * nur diese Sprache fehlen, statt die gesamte Übersetzung abzubrechen.
     */
    private async loadAllTranslations(): Promise<void> {
        if (this.allTranslations) {
            return;
        }
        const cache: Partial<Record<ioBroker.Languages, Record<string, string>>> = {};
        for (const l of Library.SUPPORTED_LANGUAGES) {
            try {
                cache[l] = this.loadTranslationFile(this.standardTranslationPath(l));
            } catch {
                this.log.warn(`Translations for language '${l}' not found`);
            }
        }
        this.allTranslations = cache;
    }

    async getTranslationObj(key: string): Promise<ioBroker.StringOrTranslated> {
        await this.loadAllTranslations();
        const result: Partial<Record<ioBroker.Languages, string>> = {};
        for (const l of Library.SUPPORTED_LANGUAGES) {
            const dict = this.allTranslations?.[l];
            if (dict && dict[key] !== undefined) {
                result[l] = dict[key];
            }
        }
        if (result.en == undefined) {
            if (this.adapter.config.logUnknownTokens) {
                this.unknownTokens[key] = '';
            }
            return key;
        }
        return result as ioBroker.StringOrTranslated;
    }

    async checkLanguage(): Promise<void> {
        try {
            this.log.debug(`Load language ${this.adapter.language}`);
            this.translation.standard = this.loadTranslationFile(this.standardTranslationPath(this.adapter.language));
        } catch {
            this.log.warn(`Standard: Language ${this.adapter.language} not exist!`);
        }
        try {
            this.log.debug(`Load language ${this.adapter.language} from custom`);
            this.translation.custom = this.loadTranslationFile(this.customTranslationPath(this.adapter.language));
        } catch {
            this.log.warn(`Custom: Language ${this.adapter.language} not exist!`);
        }
    }
    sortText(text: string[]): string[] {
        text.sort((a, b) => {
            const nameA = a.toUpperCase(); // ignore upper and lowercase
            const nameB = b.toUpperCase(); // ignore upper and lowercase
            if (nameA < nameB) {
                return -1;
            }
            if (nameA > nameB) {
                return 1;
            }

            return 0;
        });
        return text;
    }
    /**
     *
     * @param text string to replace a Date
     * @param noti appendix to translation key
     * @param day true = Mo, 12.05 - false = 12.05
     * @returns Monday first March
     */
    convertSpeakDate(text: string, noti: string = '', day = false): string {
        if (!text || typeof text !== `string`) {
            return ``;
        }
        const b = text.split(`.`);
        if (day) {
            b[0] = b[0].split(' ')[2];
        }
        return ` ${`${new Date(`${b[1]}/${b[0]}/${new Date().getFullYear()}`).toLocaleString(this.getLocalLanguage(), {
            weekday: day ? 'long' : undefined,
            day: 'numeric',
            month: `long`,
        })} `.replace(/([0-9]+\.)/gu, x => {
            const result = this.getTranslation(x + noti);
            if (result != x + noti) {
                return result;
            }
            return this.getTranslation(x);
        })}`;
    }

    /**
     * Übersetzt einen Token mit optionalen Platzhaltern
     *
     * @param token Der Übersetzungs-Token
     * @param args Optionale Argumente für Platzhalter (%s)
     * @returns Der übersetzte String
     */
    public translate(token: string, ...args: (string | number)[]): string {
        // Hole Übersetzung aus i18n oder verwende Token als Fallback
        let text = this.getTranslation(token);

        // Ersetze %s Platzhalter mit den Argumenten
        args.forEach(arg => {
            text = text.replace('%s', String(arg));
        });

        return text;
    }

    /**
     * Prüft den Verspätungsstatus.
     *
     * @param Delay Verspätung in Sekunden (null = keine Daten, undefined = keine Verspätung)
     * @param offSet Zeitoffset in minuten
     * @returns [delayed, onTime] - delayed=true wenn verspätet, onTime=true wenn pünktlich
     */
    async getDelayStatus(Delay: number | null | undefined, offSet: number): Promise<[boolean, boolean]> {
        if (Delay === null || Delay === undefined) {
            return [false, false]; // Keine Daten verfügbar
        }
        const delayed = Delay - offSet * 60 > 0;
        const onTime = Delay - offSet * 60 <= 0;
        return [delayed, onTime];
    }
}

/**
 * Konvertiert einen kebab-case String in camelCase.
 * Beispiel: "regional-express" → "regionalExpress"
 *
 * @param str   kebab-case String
 * @returns     camelCase String
 */
export function kebabToCamel(str: string): string {
    return str.replace(/-([a-z])/g, (_, char: string) => char.toUpperCase());
}

/** Umkehrmapping: camelCase-Keys → HAFAS-Produktnamen (mit Bindestrichen) */
const CAMEL_TO_KEBAB_MAP: Record<string, string> = {
    dialARide: 'dial-a-ride',
    expressTrain: 'express-train',
    nationalTrain: 'national-train',
    localTrain: 'local-train',
    // RMV-spezifische Produkt-IDs (hafas-client/p/rmv/products.js)
    sBahn: 's-bahn',
    uBahn: 'u-bahn',
    longDistanceTrain: 'long-distance-train',
    regionaTrain: 'regiona-train', // [sic] Schreibweise wie im Upstream-Profil (rmv)
    regionalTrain: 'regional-train', // vmt-Produkt-ID (RE/RB)
    cableCar: 'cable-car',
};

/**
 * Konvertiert bekannte camelCase-Produktkeys zurück in HAFAS-kebab-case-Namen.
 * Nur die explizit definierten Einträge werden konvertiert; alle anderen werden unverändert zurückgegeben.
 * Beispiel: "dialARide" → "dial-a-ride"
 *
 * @param str   camelCase String
 * @returns     kebab-case String oder unveränderten Input
 */
export function camelToKebab(str: string): string {
    return CAMEL_TO_KEBAB_MAP[str] ?? str;
}
